"""YAML renderer — standard library only (no PyYAML dependency)."""

import warnings

# Suppress the RuntimeWarning that occurs when `python -m plugins.yaml_out`
# is run directly. Python's import machinery puts the module in sys.modules
# before executing it, which triggers this warning. It's harmless.
warnings.filterwarnings("ignore", ".*plugins.yaml_out.*", RuntimeWarning)

try:
    from plugins import PluginError, Renderer, register
except ImportError:
    # Standalone execution (e.g. `python -m plugins.yaml_out`); define stubs.
    class PluginError(Exception):
        pass

    class Renderer:
        def render(self, rows):
            raise NotImplementedError

    def register(name):
        def deco(cls):
            return cls
        return deco


def _yaml_value(v) -> str:
    """Return a YAML scalar string for *v*."""
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return repr(v)
    s = str(v)
    # Quote strings that could be misinterpreted as other YAML types.
    if s.lower() in ("true", "false", "null", "yes", "no", "on", "off",
                      "null", "~", ""):
        return f"'{s}'"
    # Quote strings containing special characters.
    if any(c in s for c in (":", "{", "}", "[", "]", ",", "&", "*", "?", "|",
                            "-", "<", ">", "=", "!", "%", "@", "`", "\n")):
        return f"'{s}'"
    return s


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")

        keys = list(rows[0].keys())
        lines: list[str] = []
        for row in rows:
            if list(row.keys()) != keys:
                raise PluginError("all rows must share the same keys")
            lines.append("-")
            for k in keys:
                lines.append(f"  {k}: {_yaml_value(row[k])}")
        return "\n".join(lines) + "\n"

