"""YAML renderer – standard-library only (uses _yaml_ emitter, no PyYAML)."""

from plugins import PluginError, Renderer, register


def _yaml_dump(rows: list[dict]) -> str:
    """Minimal YAML emitter for a list of flat dicts (stdlib only)."""
    if not rows:
        return ""
    keys = list(rows[0])
    lines: list[str] = []
    for row in rows:
        lines.append("-")
        for k in keys:
            val = row[k]
            if val is None:
                lines.append(f"  {k}:")
            elif isinstance(val, str):
                # Quote strings that could be misinterpreted, or that
                # contain special YAML characters.
                if val == "" or any(c in val for c in ":{}[]&*?|->!%@`,#'\n\r\"\\") or val[0] in (" ", "\t") or val[-1] in (" ", "\t"):
                    escaped = val.replace("\\", "\\\\").replace('"', '\\"')
                    lines.append(f'  {k}: "{escaped}"')
                else:
                    lines.append(f"  {k}: {val}")
            elif isinstance(val, bool):
                lines.append(f"  {k}: {'true' if val else 'false'}")
            elif isinstance(val, int):
                lines.append(f"  {k}: {val}")
            elif isinstance(val, float):
                lines.append(f"  {k}: {val}")
            else:
                lines.append(f"  {k}: {val}")
    return "\n".join(lines) + "\n"


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        return _yaml_dump(rows)

